pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // helper that always accepts transferFrom-style calls and returns true (no revert)
    contract GoodToken {
        event Called(address from, address to, uint256 v);
        // match selector transferFrom(address,address,uint256)
        function transferFrom(address from, address to, uint256 v) external returns (bool) {
            emit Called(from, to, v);
            return true;
        }
    }

    function setUp() public { c = new C(); }

    // fuzz parameters: from address, number of tos (as uint8), value v
    function testFuzz_property(address from, uint8 tosCount, uint256 v) public {
        // keep tosCount reasonable but allow zero to be excluded; require >0 per contract
        vm.assume(tosCount > 0);
        // deploy a helper that will succeed on calls
        GoodToken t = new GoodToken();

        // build an array of distinct addresses to pass as _tos; fuzzing provides only tosCount
        address[] memory tos = new address[](tosCount);
        for (uint i = 0; i < tosCount; i++) {
            // derive addresses from i to ensure they are non-zero but arbitrary
            tos[i] = address(uint160(uint(keccak256(abi.encodePacked(from, i, block.timestamp)))));
        }

        // call transfer and capture whether it returns true (call completes)
        bool ok;
        try c.transfer(from, address(t), tos, v) returns (bool ret) {
            ok = ret; // record returned bool
        } catch {
            ok = false; // if it reverted treat as false
        }

        // GENERAL ASSERTION: reference implementation always returns true (ok == true) for any inputs
        // where the external callee (here GoodToken) succeeds; the mutant that returns false will make this fail
        assertTrue(ok);
    }
}

