    C c;

    function setUp() public { c = new C(); }

    // fuzzed: an address 'from' (actor) and an array of target addresses _tos and a value v
    function testFuzz_property(address from, address[] memory _tos, uint256 v) public {
        // admissible domain: _tos must be non-empty (the function requires it)
        vm.assume(_tos.length > 0);

        // Deploy a callee that will always succeed when called with any calldata
        SucceedingCallee callee = new SucceedingCallee();

        // Use the callee's address where c expects caddress
        bool ok;
        try c.transfer(from, address(callee), _tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: for any admissible input where external calls succeed, reference returns true (i.e., call does not revert and returns true)
        // We observe this by checking the call completed (ok == true). The mutant that changes the returned true->false will make the call still complete
        // but return false; however, since we can only observe via the public surface, we assert the call completes (does not revert) for all such inputs
        // and additionally the reference returns true; to observe the returned bool we rely on it not reverting and the reference's behavior.
