// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    GoodCallee good;

    function setUp() public { c = new C(); good = new GoodCallee(); }

    // fuzzed params: an address 'from' and an array of addresses _tos encoded as bytes to allow fuzzing length
    function testFuzz_property(address from, bytes memory tosEncoded) public {
        // decode tosEncoded to an address[] but keep domain wide; if empty, skip because contract requires non-empty
        address[] memory _tos = _decodeAddresses(tosEncoded);
        vm.assume(_tos.length > 0);

        // Use the GoodCallee which always returns success for the low-level call.
        // The reference contract should complete (return true) because the external calls succeed.
        // The mutant with require(!_s) would revert because it expects failure.

        bool ok;
        try c.transfer(from, address(good), _tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: for any non-empty _tos and a callee that succeeds, the reference completes (ok == true).
        // This will fail on the mutant for some inputs (when callee succeeds and _tos non-empty).
        assertTrue(ok);
    }

    // helper to decode arbitrary bytes into an address[]; keeps fuzzing flexible
    function _decodeAddresses(bytes memory b) internal pure returns (address[] memory) {
        if (b.length < 20) {
            address[] memory empty = new address[](0);
            return empty;
        }
        // interpret as concatenated 20-byte addresses
        uint count = b.length / 20;
        address[] memory addrs = new address[](count);
        for (uint i = 0; i < count; i++) {
            uint offset = i * 20;
            address a;
            assembly {
                a := div(mload(add(add(b, 0x20), offset)), 0x1000000000000000000000000)
            }
            addrs[i] = a;
        }
        return addrs;
    }
}

// Adversarial counterpart: a callee whose fallback accepts the call and returns (i.e., does not revert).
contract GoodCallee {
    // matching signature transferFrom(address,address,uint256) encoded via selector; just return true-ish by doing nothing
    fallback() external payable {
        // succeed silently
    }
}
